{
  "world_id": "wld_greenhold",
  "name": "The Lattice of Greenholds",
  "description": "Earth's climate has tipped into a volatile new age of heat, salt storms, and long dry seasons. Humanity survives in Greenholds: linked arcologies that use solar arrays, reclaimed water, and carefully tended living systems to shelter their communities. Beyond their walls, the Wastes are dangerous but not empty; hardy plants and small settlements persist in the margins. As a rogue weather satellite turns its attention toward the western arcology, a young engineer and a reclusive botanist must cross that harsh terrain to find a forgotten seed vault before a solar storm disrupts the systems keeping the Greenholds alive. The world is hopeful without being easy: repair, trust, and shared knowledge may yet make a future larger than survival. One odd legacy of the old climate network is that its satellites mistake broad bands of flowering plants for cool clouds, so restoring a seed corridor might redirect the machine as well as heal the land.",
  "locations": [
    {
      "id": "loc_western_greenhold",
      "name": "Westglass Greenhold",
      "description": "A western arcology built around a terraced reservoir and a wide field of solar mirrors. Its cooling system is failing under the satellite's shifting heat patterns, while residents debate whether to conserve power or keep its public gardens alive."
    },
    {
      "id": "loc_suncourt",
      "name": "Suncourt",
      "description": "A neighboring Greenhold whose stepped rooftops harvest sunlight and whose shaded lanes connect homes, workshops, and food gardens. Its council can offer supplies and technical records, but fears that helping Westglass will leave its own people exposed."
    },
    {
      "id": "loc_glasswaste",
      "name": "The Glass Waste",
      "description": "A broad, sun-blasted basin where old roads have fused into pale ridges and wind carries mineral dust. The safest route follows patches of deep-rooted scrub, which also confuse the weather satellite's heat readings."
    },
    {
      "id": "loc_reedline",
      "name": "Reedline",
      "description": "A small settlement clustered around a brackish spring and a maze of resilient reeds. Its residents know how to cross the basin without wasting water, and they preserve oral maps that contradict the Greenholds' official charts."
    },
    {
      "id": "loc_seedvault",
      "name": "The Quiet Vault",
      "description": "A buried seed repository beneath an abandoned agricultural station. Its entrance is sealed by a living root system that responds to warmth and moisture; inside are plant varieties selected to thrive in the altered climate and a record of the old satellite network."
    }
  ],
  "factions": [
    {
      "id": "fac_lattice_council",
      "name": "Lattice Council",
      "description": "Delegates from the Greenholds who coordinate power, water, and shared repairs. They value stability, but their cautious policies can leave distant communities waiting while danger grows.",
      "location_ids": [
        "loc_western_greenhold",
        "loc_suncourt"
      ]
    },
    {
      "id": "fac_reedline_wayfinders",
      "name": "Reedline Wayfinders",
      "description": "Guides and seed keepers who maintain routes through the Wastes. They protect local knowledge and expect visitors to contribute labor or useful information rather than simply take supplies.",
      "location_ids": [
        "loc_reedline",
        "loc_glasswaste"
      ]
    },
    {
      "id": "fac_canopy_keepers",
      "name": "Canopy Keepers",
      "description": "A loose circle of botanists and caretakers who guard surviving plant collections. They believe the Quiet Vault should be opened only with a plan to distribute its seeds fairly and restore the land beyond the arcologies.",
      "location_ids": [
        "loc_seedvault",
        "loc_western_greenhold"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_solar_dependence",
      "statement": "Every Greenhold depends on solar power for its cooling, water treatment, and controlled growing spaces.",
      "category": "technology"
    },
    {
      "id": "rul_water_limits",
      "statement": "Clean water is finite in the Wastes; settlements survive by capturing seasonal runoff, reusing household water, and protecting springs.",
      "category": "other"
    },
    {
      "id": "rul_satellite_heat",
      "statement": "The weather satellite reads surface heat imperfectly, and broad bands of flowering plants can appear to it as cool cloud cover.",
      "category": "technology"
    },
    {
      "id": "rul_shared_repairs",
      "statement": "No Greenhold can maintain its full power and food systems alone; shared parts and practical knowledge are necessary for long-term survival.",
      "category": "social"
    },
    {
      "id": "rul_vault_roots",
      "statement": "The Quiet Vault's living root seal opens only when warmth and moisture reach it in a measured balance.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_climate_threshold",
      "name": "The Long Thaw",
      "description": "Rising seas, crop failures, and repeated heat emergencies forced communities to build sheltered settlements around renewable power and carefully managed water.",
      "era": "The Collapse",
      "location_ids": [
        "loc_western_greenhold",
        "loc_suncourt"
      ]
    },
    {
      "id": "evt_network_compact",
      "name": "The Lattice Compact",
      "description": "The first Greenholds agreed to share energy equipment, seed stock, and repair crews. The compact kept the arcologies connected, though arguments over who received help first never disappeared.",
      "era": "Early Greenhold Years",
      "location_ids": [
        "loc_western_greenhold",
        "loc_suncourt"
      ]
    },
    {
      "id": "evt_satellite_silence",
      "name": "The Silent Forecast",
      "description": "The climate network stopped accepting human guidance. Its satellites continued to steer storms using damaged models, and the people of the Greenholds learned to watch the sky as closely as their instruments.",
      "era": "The Unanswered Years",
      "location_ids": [
        "loc_western_greenhold",
        "loc_glasswaste"
      ]
    },
    {
      "id": "evt_reedline_maps",
      "name": "Maps in Reed",
      "description": "Reedline families began preserving routes as spoken songs, updated whenever springs shifted or old roads vanished. Their maps became more reliable than the Greenholds' inherited charts.",
      "era": "The Unanswered Years",
      "location_ids": [
        "loc_reedline",
        "loc_glasswaste"
      ]
    },
    {
      "id": "evt_vault_discovery",
      "name": "The Rooted Door",
      "description": "A botanist found traces of the buried repository beneath the abandoned station, but kept its location secret until there was a way to protect its seeds and share them beyond the arcologies.",
      "era": "Recent Years",
      "location_ids": [
        "loc_seedvault"
      ]
    },
    {
      "id": "evt_westglass_alert",
      "name": "The Red Horizon",
      "description": "A new satellite track placed Westglass in the path of an intensifying heat event. The warning gave its people little time to repair their cooling network or find another way to redirect the machine.",
      "era": "Present Day",
      "location_ids": [
        "loc_western_greenhold",
        "loc_suncourt"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_save_or_share",
      "name": "Shelter or Seed",
      "description": "The Lattice Council wants the vault's resources directed first toward Westglass's failing systems. The Canopy Keepers insist that seeds and knowledge must be shared with settlements beyond the Greenholds, even if that slows emergency repairs.",
      "faction_ids": [
        "fac_lattice_council",
        "fac_canopy_keepers"
      ]
    },
    {
      "id": "cnf_route_trust",
      "name": "The Unmarked Crossing",
      "description": "The Wayfinders know a safer route across the Glass Waste, but distrust the Greenholds' official missions and refuse to reveal it without an agreement that respects Reedline's independence.",
      "faction_ids": [
        "fac_lattice_council",
        "fac_reedline_wayfinders"
      ]
    },
    {
      "id": "cnf_satellite_clock",
      "name": "A Narrow Window",
      "description": "The approaching heat event leaves little time to reach the Quiet Vault and test whether its flowering plants can mislead the satellite. A rushed attempt could destroy the vault's living seal; delay could cost Westglass its cooling system.",
      "faction_ids": [
        "fac_canopy_keepers",
        "fac_reedline_wayfinders",
        "fac_lattice_council"
      ]
    }
  ]
}
